'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function verifiedBadge(p){return p?.verified?'<span class="verified-badge" role="img" aria-label="Cuenta verificada" title="Cuenta verificada"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" stroke="none" d="m12 1 3 2.2 3.7.1 1.1 3.5 3 2.2-1.1 3.5 1.1 3.5-3 2.2-1.1 3.5-3.7.1L12 24l-3-2.2-3.7-.1-1.1-3.5-3-2.2 1.1-3.5L1.2 9l3-2.2 1.1-3.5 3.7-.1z"/><path d="m7.5 12 3 3 6-6" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>':'';}
const norm = v => String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const icons = {
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-8h6v8"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M15 3.1a4 4 0 0 1 0 7.8"/><circle cx="9" cy="7" r="4"/>',chat:'<path d="M21 11.5A8.4 8.4 0 0 1 12.5 20a9 9 0 0 1-4-.9L3 21l1.9-5.5a9 9 0 0 1-.9-4A8.4 8.4 0 0 1 12.5 3h.5a8.4 8.4 0 0 1 8 8z"/><path d="M8 11h8m-8 4h5"/>',news:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8m-8 4h8m-8 4h3m3 0h2m-8 3h8"/>',game:'<path d="M7 7h10c4 0 6 12 3 13-2 1-4-4-5-4H9c-1 0-3 5-5 4-3-1-1-13 3-13zM8 10v5m-2.5-2.5h5M16 11h.01M18 14h.01M12 7V3"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',external:'<path d="M14 3h7v7m-1-6-10 10M10 3H3v18h18v-7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',checks:'<path d="m2 12 4 4L16 6m-5 10L21 6"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8z"/>',send:'<path d="m22 2-7 20-4-9-9-4 20-7zM22 2 11 13"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',smile:'<circle cx="12" cy="12" r="9"/><path d="M8 14s1 3 4 3 4-3 4-3M8.5 8.5h.01m7 0h.01"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',edit:'<path d="m16 3 5 5L8 21H3v-5zM13 6l5 5"/>',logout:'<path d="M9 3H3v18h6m5-14 5 5-5 5m-7-5h12"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.compass}</svg>`;
const state = { catalog:null, profiles:[],user:null,config:null,route:'inicio',filter:'todos',communityTab:'cuentas',query:'',conversations:[],active:null,messages:[],hasMore:false,chatQuery:'',chatFilter:'todos',messageSearch:'',reply:null,attachment:null,sending:false,stream:null,news:[],firebase:null,recording:null,modal:null,authMode:'login',selectedAvatar:null,typingAt:0,requestSequence:0 };
const time = ts => new Date(ts).toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});
const date = ts => new Date(ts).toLocaleDateString('es-CO',{day:'numeric',month:'long',year:'numeric'});
const shortDate = ts => new Date(ts).toDateString()===new Date().toDateString()?time(ts):new Date(ts).toLocaleDateString('es-CO',{day:'2-digit',month:'short'});
const character = name => state.catalog.characters.find(c=>c.name===name);
const refreshedAsset = src => src+'?v=20261017';
const imageFor = name => refreshedAsset(character(name)?.image || 'personajes/dani.png');
const avatar = (p,cls='') => `<span class="avatar-wrap"><img class="avatar ${cls}" src="${esc(imageFor(p.avatar||p.name))}" alt="${esc(p.name)}" loading="lazy">${p.online?'<i class="online-dot" title="En línea"></i>':''}</span>`;
const getProfile = id => state.profiles.find(p=>p.id===id);
const allContent = () => Object.values(state.catalog.content).flat();
const saved = id => state.user?.saved.includes(id);
const toast = (message,error=false) => {const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),5500);};
async function api(url, options={}) {
  if(state.publicOnly)throw new Error('La comunidad todavía no está disponible. Puedes seguir explorando las temporadas, los personajes y los simuladores.');
  let response;
  try {response=await fetch('/api'+url,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});}catch{setConnection(false);throw new Error('No hay conexión con el servidor. Tu borrador sigue aquí; vuelve a intentar.');}
  let result;
  try{result=await response.json();}catch{const error=new Error('El servidor de la comunidad no está disponible en esta dirección.');error.status=response.status;throw error;}
  if(!response.ok){if(response.status===401&&state.user){state.user=null;stopStream();renderChrome();}const error=new Error(result.error||'No se pudo completar la operación.');error.status=response.status;throw error;}
  return result;
}
function setConnection(online){const el=$('#connection');el.classList.toggle('offline',!online);el.innerHTML=`<i></i><span>${online?'En línea':'Sin conexión'}</span>`;}
function errorView(error){$('#main').innerHTML=`<div class="error-panel"><div class="eyebrow" style="justify-content:center">THE XPEDITION</div><h1 style="margin-top:20px">Conectemos tu universo.</h1><p>${esc(error.message)}</p><button class="btn primary" data-action="retry">Volver a intentar</button><p>Abre la web con <strong>ABRIR XPEDITION.cmd</strong> para iniciar el servidor y guardar los datos.</p></div>`;}
const navItems=[['inicio','home','Inicio'],['explorar','compass','Explorar'],['comunidad','users','Comunidad'],['mensajes','chat','Mensajes'],['noticias','news','Noticias'],['simuladores','game','Simuladores'],['guardados','bookmark','Mi lista'],['universo','info','El universo']];
function renderChrome(){
  const unread=state.conversations.reduce((n,c)=>n+c.unread,0);
  $('#navigation').innerHTML=navItems.map(([route,ico,label],i)=>`${i===6?'<div class="nav-separator"></div>':''}<a href="#${route}" class="nav-link ${state.route===route?'active':''} ${i>=5?'desktop-only':''}" ${state.route===route?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${route==='mensajes'&&unread?`<span class="count">${unread>99?'99+':unread}</span>`:''}</a>`).join('');
  $('#breadcrumb').textContent=state.route==='inicio'?'Tu universo, en un solo lugar.':navItems.find(n=>n[0]===state.route)?.[2]||'Un perfil, muchas historias.';
  $('#accountActions').innerHTML=state.user?`<button class="icon-button" data-action="go-messages" aria-label="Ver mensajes">${icon('chat')}</button><button data-action="account-menu" aria-label="Opciones de ${esc(state.user.name)}" aria-expanded="false">${avatar(state.user)}</button>`:`<button class="link-button" data-action="login">Entrar</button><button class="btn primary small" data-action="register">Únete al universo ${icon('arrow')}</button>`;
  $('#sidebarBottom').innerHTML=state.user?`<div class="join-card"><span class="eyebrow">TU EXPEDICIÓN</span><h3>${esc(state.user.name)}</h3><p>Tu perfil, tus conversaciones y las historias que sigues.</p><button class="btn secondary full small" data-action="my-profile">Ver mi perfil ${icon('arrow')}</button></div>`:`<div class="join-card"><span class="orbit">✳</span><h3>Hay un lugar para ti.</h3><p>Crea tu perfil. Encuentra a tu gente. Vive el universo desde dentro.</p><button class="btn primary full small" data-action="register">Crear mi perfil ${icon('arrow')}</button></div>`;
  document.title='The Xpedition';
}
const contentArt = item => item.art?.background||(item.kind==='Campria'?`${item.season} Portada.png`:`backdrops/${({antarctica:'antarctica.jpg',safari:'safari.jpg',japan:'japan.png',showdown2:'showdown.png','safari-showdown':'showdown-season-1.png','traitor-showdown':'showdown-season-2.png'})[item.id]||item.id+'.png'}`);
const logoFor = item => item.art?.logo?.src||(item.kind==='Simulador'||item.kind==='Campria'?null:({antarctica:'transparent/antarctica.png',safari:'transparent/safari.png',japan:'transparent/japan.png',traitor:'transparent/traitor.png',traitor2:'transparent/traitor2.png',traitor3:'transparent/traitor3.png','safari-showdown':'transparent/showdown.png','traitor-showdown':'transparent/showdown2.png'})[item.id]);
const logoFrames={antarctica:[254,432,1341,694],safari:[328,431,1268,700],japan:[262,252,1333,1097],traitor:[139,299,1508,871],traitor2:[146,297,1497,1078],traitor3:[146,297,1497,1126],showdown:[165,433,1466,658],showdown2:[66,435,1711,665]};
function brandArt(item,cls='season-logo'){
  const src=logoFor(item);if(!src)return '';
  const key=src.split('/').pop().replace('.png',''),frame=item.art?.logo?.frame||logoFrames[key]||[0,0,1800,1600];
  return `<svg class="brand-art ${cls}" data-brand="${key}" viewBox="${frame.join(' ')}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(item.name)}"><image href="${esc(refreshedAsset(src))}" width="${item.art?.logo?.width||1800}" height="${item.art?.logo?.height||1600}"/></svg>`;
}
function contentCard(item){
  const simulator=item.kind==='Simulador';
  return `<article class="season-card ${simulator?'simulator-card':item.kind==='Campria'?'campria-card':item.saga==='diamond-rush'?'diamond-rush-card':item.kind==='Awards'?'awards-card':''}" data-content-id="${esc(item.id)}"><button class="season-art" data-action="content" data-id="${esc(item.id)}" data-kind="${esc(item.kind)}" aria-label="Ver ${esc(item.name)}"><img class="season-background" src="${esc(contentArt(item))}" alt="${simulator?esc(item.name):''}" loading="lazy" decoding="async">${item.art?.poster?`<img class="season-poster" src="${esc(item.art.poster)}" alt="" loading="lazy" decoding="async">`:''}${brandArt(item)}<span class="season-label ${item.disabled?'upcoming-label':''}">${item.disabled||item.upcoming?'Próximamente':esc(item.kind==='Campria'||item.kind==='Awards'?item.season:item.kind==='Spin Off'?'Spin-off':item.kind)}</span><span class="card-reveal" aria-hidden="true">${icon(simulator?'game':'info')}</span></button><button class="save-button ${saved(item.id)?'saved':''}" data-action="save" data-id="${esc(item.id)}" aria-label="${saved(item.id)?'Quitar de':'Añadir a'} mi lista: ${esc(item.name)}" aria-pressed="${!!saved(item.id)}">${icon(saved(item.id)?'check':'plus')}</button><div class="season-info"><h3>${esc(item.name)}</h3><p>${esc(item.meta.replace('Season','Temporada'))}</p>${item.critics?criticsBadge(item):''}${simulator?`<p class="simulator-description">${esc(item.desc)}</p><a class="simulator-play" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Jugar ahora ${icon('arrow')}</a>`:''}</div></article>`;
}
const heading=(title,sub,extra='')=>`<div class="page-heading"><div><div class="eyebrow" style="margin-bottom:10px"><span class="dot"></span> THE XPEDITION UNIVERSE</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;
const empty=(title,text,action='',label='',ico='compass')=>`<div class="empty-state"><div class="empty-symbol">${icon(ico)}</div><h2>${title}</h2><p>${text}</p>${action?`<button class="btn primary" data-action="${action}">${label} ${icon('arrow')}</button>`:''}</div>`;
function renderHome(){
  const c=state.catalog.content;
  $('#main').innerHTML=`<section class="hero"><img class="hero-image" src="backdrops/antarctica.jpg" alt="The Xpedition Antarctica"><div class="hero-copy"><div class="eyebrow"><span class="dot"></span> AQUÍ EMPIEZA TU EXPEDICIÓN</div><div class="hero-meta"><span>THE XPEDITION</span><i></i><span>COMPETENCIA · COMUNIDAD</span></div><h1>El desafío es real.<br>La historia es <span>tuya.</span></h1><p>Temporadas inolvidables, alianzas inesperadas y una comunidad con mucho por contar. Bienvenid@ a tu universo.</p><div class="hero-actions"><button class="btn primary" data-action="content" data-id="antarctica">Explorar Antarctica ${icon('arrow')}</button><a href="#comunidad" class="btn secondary">La comunidad</a></div></div><div class="hero-edition">EL ORIGEN DE TODO<strong>ANTARCTICA</strong>SEASON 01 / 2022</div></section>
  <div class="intro-strip"><div class="stacked-avatars">${['Dani','Bonju','Ignacio Ricci','Julián'].map(n=>`<img class="avatar" src="${esc(imageFor(n))}" alt="${esc(n)}">`).join('')}</div><div><strong>Las historias se viven mejor en comunidad.</strong><p>Crea tu perfil y conecta con otros exploradores.</p></div><a class="link-button" href="#comunidad">Encuentra a tu gente ${icon('arrow')}</a></div>
  <section><div class="section-head"><div><h2><span class="section-index">01 /</span>Elige tu próxima aventura</h2><p>El universo The Xpedition, temporada a temporada.</p></div><a href="#explorar" class="link-button">Ver todo ${icon('arrow')}</a></div><div class="content-grid">${c.xpedition.map(contentCard).join('')}</div></section>
  <section><div class="section-head"><div><h2><span class="section-index">02 /</span>El juego está en tus manos</h2><p>Crea alianzas, toma decisiones y cambia el destino.</p></div><a href="#simuladores" class="link-button">Jugar ${icon('arrow')}</a></div><div class="content-grid four-grid">${c.simulators.map(contentCard).join('')}</div></section>
  <section><div class="section-head"><div><h2><span class="section-index">03 /</span>Dentro del universo</h2><p>Las historias detrás de la competencia.</p></div><a href="#noticias" class="link-button">Todas las noticias ${icon('arrow')}</a></div><div class="news-grid">${state.catalog.news.slice(0,2).map(newsCard).join('')}</div></section>`;
}
function renderExplore(){
  const categories=[['todos','Todo el universo'],['xpedition','The Xpedition'],['spinoffs','Spin-offs'],['campria','Campria']];
  let items=state.filter==='todos'?[...state.catalog.content.xpedition,...state.catalog.content.spinoffs,...state.catalog.content.campria]:(state.catalog.content[state.filter]||[]);
  items=items.filter(c=>norm(c.name+' '+c.meta).includes(norm(state.query)));
  $('#main').innerHTML=heading('Un universo por descubrir.','De los primeros desafíos a las nuevas historias. Encuentra tu temporada.')+`<div class="chips">${categories.map(([id,label])=>`<button class="chip ${state.filter===id?'active':''}" data-action="explore-filter" data-id="${id}">${label}</button>`).join('')}</div><label class="search-field">${icon('search')}<input id="exploreSearch" placeholder="Buscar una temporada…" aria-label="Buscar temporada" value="${esc(state.query)}"></label><div class="content-grid" id="exploreResults">${items.map(contentCard).join('')}</div>`;
}
function memberCard(p){const following=state.user?.follows.includes(p.id);return `<article class="member-card"><button data-action="profile" data-id="${esc(p.id)}">${avatar(p)}<h3>${esc(p.name)}${verifiedBadge(p)}</h3></button><p>${p.staff?'Staff de The Xpedition':p.character?'Personaje del universo':p.online?'En línea ahora':'Miembro de la comunidad'} · ${p.followers} seguidores</p><div class="member-buttons"><button class="btn ${following?'secondary':'primary'} small" data-action="follow" data-id="${esc(p.id)}" ${p.id===state.user?.id?'disabled':''}>${p.id===state.user?.id?'Tu perfil':following?'Siguiendo':'+ Seguir'}</button>${!p.character&&p.id!==state.user?.id?`<button class="btn ghost small" data-action="start-dm" data-id="${esc(p.id)}" aria-label="Escribir a ${esc(p.name)}">${icon('chat')}</button>`:''}</div></article>`;}
function communityResults(){const list=state.profiles.filter(p=>(state.communityTab==='personajes'?p.character:state.communityTab==='siguiendo'?state.user?.follows.includes(p.id):!p.character)&&norm(p.name).includes(norm(state.query)));$('#communityResults').innerHTML=list.map(memberCard).join('')||empty(state.communityTab==='cuentas'?'La comunidad empieza contigo.':'No hay perfiles aquí todavía.','Invita a tus amigos a crear sus cuentas y a formar parte de la próxima aventura.',!state.user?'register':'new-chat',!state.user?'Crear mi perfil':'Iniciar conversación','users');$('#communityCount').textContent=list.length+' perfiles';}
function renderCommunity(){
  if(state.publicOnly){
    state.communityTab='personajes';
    $('#main').innerHTML=heading('Los rostros del universo.','Explora las historias y los logros de los personajes de cada temporada.')+`<div class="notice" style="margin-bottom:24px">Los perfiles personales, el seguimiento y los mensajes estarán disponibles al abrir la comunidad.</div><label class="search-field">${icon('search')}<input id="communitySearch" aria-label="Buscar perfiles" placeholder="Busca un personaje…" value="${esc(state.query)}"></label><div class="section-head" style="margin-top:16px"><h2>Personajes</h2><span class="pill" id="communityCount"></span></div><div class="members-grid" id="communityResults"></div>`;communityResults();return;
  }
  $('#main').innerHTML=heading('Encuentra a tu gente.','Perfiles, participantes y conversaciones que se convierten en historias.')+`<div class="chips"><button class="chip ${state.communityTab==='cuentas'?'active':''}" data-action="community-tab" data-id="cuentas">Comunidad</button><button class="chip ${state.communityTab==='personajes'?'active':''}" data-action="community-tab" data-id="personajes">Personajes · ${state.catalog.characters.length}</button><button class="chip ${state.communityTab==='siguiendo'?'active':''}" data-action="community-tab" data-id="siguiendo">Siguiendo</button></div><label class="search-field">${icon('search')}<input id="communitySearch" aria-label="Buscar perfiles" placeholder="Busca un nombre, encuentra una historia…" value="${esc(state.query)}"></label><div class="section-head" style="margin-top:16px"><h2>${state.communityTab==='personajes'?'Los rostros del universo':'Exploradores'}</h2><span class="pill" id="communityCount"></span></div><div class="members-grid" id="communityResults"></div>`;communityResults();
}
function newsImage(n){const map={'simuladores-mejoras-2025':['backdrops/house.png','Simuladores'],'traitor-2-pagina-oficial':['backdrops/traitor2.png','The Traitor'],'bonju-camp-awards':[imageFor('Bonju'),'Comunidad',true],'xpedition-japan-location':['backdrops/japan.png','Nueva temporada'],'ignacio-ricci-showdown-2-winner':[imageFor('Ignacio Ricci'),'Participantes',true],'julian-fuera-final-safari':[imageFor('Julián'),'Safari',true],'safari-regreso-2025':['backdrops/safari.jpg','Safari'],'dani-ganadora-antarctica':[imageFor('Dani'),'Antarctica',true]};return map[n.id]||['backdrops/antarctica.jpg','Universo'];}
function newsCard(n){const [image,category,portrait]=newsImage(n),likes=state.news.find(x=>x.id===n.id);return `<article class="news-card"><div class="news-art ${portrait?'portrait':''}" ${portrait?`style="--portrait-bg:${esc(n.portraitBackground||'#191321')}"`:''}><img src="${esc(image)}" alt="${esc(n.title)}" loading="lazy"><span class="pill">${category}</span></div><div class="news-body"><div class="news-byline"><img class="avatar tiny" src="${esc(imageFor(n.author))}" alt=""><span>${esc(n.author)} · ${esc(n.role)}</span></div><h2>${esc(n.title)}</h2><p>${esc(n.text)}</p><div class="news-actions"><button class="${likes?.liked?'liked':''}" data-action="news-like" data-id="${esc(n.id)}" aria-pressed="${!!likes?.liked}">${icon('heart')} ${likes?.liked?'Te gusta':'Me gusta'} <span>${likes?.count||0}</span></button><span>Archivo del universo</span></div></div></article>`;}
function renderNews(){ $('#main').innerHTML=heading('Lo que pasa aquí, se cuenta.','Noticias, momentos y protagonistas del universo The Xpedition.')+`<div class="news-grid">${state.catalog.news.map(newsCard).join('')}</div>`; }
function renderSimulators(){ $('#main').innerHTML=heading('Tu temporada. Tus reglas.','Explora los simuladores y crea una historia diferente cada vez.')+`<div class="content-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${state.catalog.content.simulators.map(contentCard).join('')}</div><div class="notice" style="margin-top:24px">Cada simulador abre su propia experiencia. House te lleva al simulador oficial de convivencia.</div>`; }
function renderSaved(){ $('#main').innerHTML=heading('Historias para volver.','Tus temporadas y simuladores favoritos, siempre a mano.')+(state.user?`<div class="content-grid">${allContent().filter((c,i,a)=>saved(c.id)&&a.findIndex(x=>x.id===c.id)===i).map(contentCard).join('')}</div>${!state.user.saved.length?empty('Tu próxima aventura empieza aquí.','Guarda temporadas y simuladores con el botón + para tenerlos en tu lista.','go-explore','Explorar el universo','bookmark'):''}`:empty('Una lista que viaja contigo.','Inicia sesión para guardar tus favoritos y encontrarlos desde cualquier dispositivo.','login','Iniciar sesión','bookmark')); }
function renderAbout(){ $('#main').innerHTML=`<div class="about-copy"><div class="eyebrow">UN UNIVERSO HECHO DE HISTORIAS</div><h1 style="margin-top:16px">El juego nos reúne.<br>La comunidad nos mueve.</h1><p>The Xpedition es una competencia virtual inspirada en reality shows, creada para divertir, despertar la creatividad y conectar a personas a través de desafíos y decisiones inesperadas.</p><div class="about-banner"><img src="/backdrops/universe-trio-20261019.webp" alt="Bonju, Dios y Maria, los tres rostros de The Xpedition"></div><h2>Distintas sagas. Una misma aventura.</h2><p><strong>Campria</strong> fue el inicio: nuevas reglas, sistemas de eliminación y participantes que volvieron a escribir su historia temporada tras temporada. <strong>The Xpedition</strong> llevó la competencia a nuevos destinos. <strong>The Traitor</strong> añadió secretos, sospechas y el poder de una buena estrategia.</p><div class="section-head"><h2>Detrás del universo</h2></div><div class="members-grid">${['Dios','Bonju','Maria','Dua Lingo','Nidia Mirella','Edna Droga','Nicki Gorilaj','Chad Gil Pete'].map(name=>state.profiles.find(p=>p.name===name)).filter(Boolean).map(memberCard).join('')}</div></div>`; }
function renderProfile(id){
  const p=getProfile(id);if(!p){$('#main').innerHTML=empty('Este perfil no está disponible.','Vuelve a la comunidad para encontrar otros perfiles.','go-community','Ver comunidad');return;}
  const own=state.user?.id===id,following=state.user?.follows.includes(id),stats={...(p.stats||{}),followers:p.followers};
  const statNames=[['seasonsPlayed','Temporadas'],['duelWins','Duelos ganados'],['duelLosses','Duelos perdidos'],['finalsReached','Finales'],['seasonsWon','Victorias'],['retosGanados','Retos ganados'],['apariciones','Apariciones'],['bestPlacement','Mejor posición'],['followers','Seguidores']];
  $('#main').innerHTML=`<div class="profile-cover"></div><section class="profile-overview">${avatar(p)}<div class="profile-identity"><h1>${esc(p.name)}${verifiedBadge(p)}</h1><p>${p.staff?'Staff de The Xpedition':p.character?'Personaje del universo The Xpedition':own?'Este es tu lugar en el universo.':'Explorador de The Xpedition'}</p></div><div class="profile-actions">${own?`<button class="btn primary" data-action="edit-profile">${icon('edit')} Editar perfil</button><button class="btn secondary" data-action="avatar">Cambiar ícono</button>`:`<button class="btn ${following?'secondary':'primary'}" data-action="follow" data-id="${esc(id)}">${icon(following?'check':'plus')} ${following?'Siguiendo':'Seguir'}</button>${!p.character?`<button class="btn secondary" data-action="start-dm" data-id="${esc(id)}">${icon('chat')} Mensaje</button>`:''}`}</div></section><div class="profile-layout"><aside><div class="panel"><div class="profile-counts"><button data-action="followers" data-id="${esc(id)}"><strong>${p.followers}</strong> seguidores</button><button data-action="following" data-id="${esc(id)}"><strong>${p.following||0}</strong> siguiendo</button></div><h3>Su historia</h3><p>${esc(p.bio||'Hay muchas historias por escribir.')}</p>${p.character?awardProfileSummary(p):''}<span class="pill ${p.character?'':'lime'}">${p.character?'PERSONAJE':p.online?'EN LÍNEA':'COMUNIDAD'}</span>${!p.character?`<p style="margin:15px 0 0;font-size:10px">En el universo desde ${date(p.created)}</p>`:''}</div>${p.character?'<div class="notice" style="margin-top:15px">Este es un perfil de personaje con estadísticas de la competencia. Los mensajes se envían entre cuentas registradas en Comunidad.</div>':''}</aside><section><div class="panel"><h2>${p.character?'Su paso por la competencia':'El próximo capítulo'}</h2>${p.character?`<div class="stats-grid">${statNames.map(([key,label])=>`<div class="stat"><strong>${esc(stats[key]??'—')}</strong><span>${label}</span></div>`).join('')}</div><div class="badges">${Object.entries(state.catalog.achievements).filter(([,names])=>names.includes(p.name)).map(([title])=>`<span class="pill lime">✧ ${esc(title)}</span>`).join('')}</div>`:`<p>Cada alianza comienza con una conversación. Sigue a otros perfiles y encuentra a tu gente en la comunidad.</p><a href="#comunidad" class="btn secondary">Explorar la comunidad ${icon('arrow')}</a>`}</div></section></div>`;
}
function renderSearch(){ $('#main').innerHTML=heading('Todo empieza con una búsqueda.','Encuentra temporadas, juegos, personajes y miembros de la comunidad.')+`<label class="search-field">${icon('search')}<input id="globalSearch" placeholder="¿Qué quieres encontrar?" aria-label="Buscar en todo el universo" autofocus></label><div id="globalResults"></div>`;setTimeout(()=>$('#globalSearch')?.focus(),20); }
function searchResults(q){const profiles=state.profiles.filter(p=>norm(p.name).includes(norm(q))),content=allContent().filter((c,i,a)=>norm(c.name).includes(norm(q))&&a.findIndex(x=>x.id===c.id)===i);$('#globalResults').innerHTML=q.length<2?'<p class="form-hint">Escribe al menos dos letras para comenzar.</p>':`<div class="section-head"><h2>Temporadas y juegos</h2><span class="pill">${content.length}</span></div><div class="content-grid">${content.map(contentCard).join('')}</div><div class="section-head"><h2>Perfiles</h2><span class="pill">${profiles.length}</span></div><div class="members-grid">${profiles.map(memberCard).join('')}</div>`;}
function route(){
  if(!state.catalog)return;cancelRecording();
  const [view,id]=location.hash.slice(1).split('/');state.route=view||'inicio';state.messageSearch='';state.query='';$('.account-menu')?.remove();document.body.classList.toggle('messaging',state.route==='mensajes');renderChrome();
  if(state.route==='explorar'&&['tops','todos','xpedition','campria','traitor','showdown','diamond-rush','awards','spinoffs'].includes(id))state.filter=id==='spinoffs'?'showdown':id;
  const routes={inicio:renderHome,explorar:renderExplore,temporada:()=>renderSeasonPage(decodeURIComponent(id||'')),audicion:()=>renderCasting(),premios:()=>renderAwardsPage(decodeURIComponent(id||'')),comunidad:renderCommunity,noticias:renderNews,simuladores:renderSimulators,guardados:renderSaved,universo:renderAbout,privacidad:()=>renderPrivacy(),moderacion:()=>renderModeration(),buscar:renderSearch,mensajes:renderMessenger,perfil:()=>renderProfile(decodeURIComponent(id||''))};
  if(state.route==='mensajes'&&id)state.active=decodeURIComponent(id);
  (routes[state.route]||renderHome)();window.scrollTo({top:0,behavior:'instant'});
}
const go = hash => {if(location.hash==='#'+hash)route();else location.hash=hash;};
function modal(html,wide=false,kind='generic'){$('#modal').classList.toggle('wide',wide);$('#modalContent').innerHTML=html;state.modal=kind;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();state.modal=null;}
function requireAuth(){if(state.user)return true;openAuth('login');return false;}
function field(label,id,type='text',placeholder='',value=''){return `<label class="form-field" for="${id}">${label}<${type==='textarea'?'textarea':'input'} id="${id}" name="${id}" ${type==='textarea'?'':`type="${type}"`} placeholder="${esc(placeholder)}" ${type==='password'?'minlength="8" maxlength="128"':type==='email'?'autocomplete="email"':`maxlength="${type==='textarea'?600:40}"`} ${type==='textarea'?'':`value="${esc(value)}"`}>${type==='textarea'?esc(value)+'</textarea>':''}</label>`;}
function openAuth(mode='login'){
  if(state.publicOnly){
    modal(`<div class="modal-kicker">THE XPEDITION UNIVERSE</div><h2 id="modalTitle">La comunidad está por abrir.</h2><p class="modal-intro">Ya puedes explorar temporadas, videos, tops, personajes y simuladores. El registro, el acceso con Google, el seguimiento y los mensajes estarán disponibles cuando activemos la comunidad.</p><button class="btn primary full" data-action="close-modal">Seguir explorando ${icon('arrow')}</button>`);return;
  }
  state.authMode=mode;
  modal(`<div class="modal-kicker">TU PRÓXIMA AVENTURA</div><h2 id="modalTitle">${mode==='register'?'Hay un lugar para ti.':'Qué bueno verte de nuevo.'}</h2><p class="modal-intro">${mode==='register'?'Tu perfil, tus alianzas y todas las historias por venir.':'Entra al universo y continúa tu historia.'}</p><div class="auth-tabs"><button data-action="login" class="${mode==='login'?'active':''}">Iniciar sesión</button><button data-action="register" class="${mode==='register'?'active':''}">Crear una cuenta</button></div><form id="authForm">${mode==='register'?field('Tu nombre de usuario','authName','text','¿Cómo te conocerá la comunidad?')+field('Correo electrónico','authEmail','email','tu@correo.com'):field('Usuario o correo','authLogin','text','Tu usuario o tu correo')}<label class="form-field" for="authPassword">Contraseña<span class="password-field"><input id="authPassword" name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" minlength="${mode==='register'?8:1}" maxlength="128" placeholder="${mode==='register'?'Mínimo 8 caracteres':'Tu contraseña'}" required><button class="icon-button" type="button" data-action="toggle-password" data-id="authPassword" aria-label="Mostrar contraseña">${icon('eye')}</button></span></label>${mode==='register'?field('Repite tu contraseña','authConfirm','password','Escríbela una vez más'):''}<p class="form-error" id="authError" role="alert"></p><button class="btn primary full" id="authSubmit" type="submit">${mode==='register'?'Crear mi cuenta':'Entrar a mi universo'} ${icon('arrow')}</button></form><div class="divider">o continúa con</div><button class="btn secondary full" id="googleButton" data-action="google" ${state.firebase?'':'disabled'}><span class="google-mark">G</span> Continuar con Google</button><p class="form-hint" style="margin:17px 0 0">${mode==='register'?'Después podrás elegir entre los '+state.catalog.characters.length+' personajes para tu ícono. Tus datos se guardan en el servidor.':'Si ya tenías una cuenta en Firebase, usa tu correo completo o continúa con Google.'}</p>`,false,'auth');
  $$('#authForm input').forEach(el=>el.required=true);if(mode==='register')$('#authEmail').autocomplete='email';else $('#authLogin').autocomplete='username';
  $('#authForm').addEventListener('submit',submitAuth);setTimeout(()=>$('#authName, #authLogin')?.focus(),30);
}
async function submitAuth(e){
  e.preventDefault();const button=$('#authSubmit');button.disabled=true;$('#authError').textContent='';
  try{
    const registering=state.authMode==='register',password=$('#authPassword').value;
    if(registering&&password!==$('#authConfirm').value)throw new Error('Las contraseñas no coinciden.');
    const values=registering?{name:$('#authName').value,email:$('#authEmail').value,password}:{login:$('#authLogin').value,password};
    const result=await api('/auth/'+(registering?'register':'login'),{method:'POST',body:values});await authenticated(result.user);closeModal();toast('¡Bienvenid@, '+state.user.name+'!');if(registering)editProfile(true);
  }catch(error){if($('#authError'))$('#authError').textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}
}
async function loadFirebase(){
  if(state.publicOnly)return;
  try{
    const [appModule,authModule]=await Promise.all([import('https://www.gstatic.com/firebasejs/10.7.1/firebase-app.js'),import('https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js')]);
    const auth=authModule.getAuth(appModule.initializeApp(state.config.firebase));const provider=new authModule.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});
    state.firebase={auth,provider,...authModule};const button=$('#googleButton');if(button)button.disabled=false;
  }catch{if($('#googleButton')){$('#googleButton').disabled=false;$('#googleButton').title='Volver a conectar con Google';}}
}
function googleLogin(){
  if(!state.firebase){toast('No se pudo cargar Google. Revisa tu conexión y vuelve a intentar.',true);loadFirebase();return;}
  const button=$('#googleButton');if(button)button.disabled=true;
  // Called directly from the user gesture, before any await, to preserve popup permission.
  state.firebase.signInWithPopup(state.firebase.auth,state.firebase.provider).then(async result=>{
    const idToken=await result.user.getIdToken();const data=await api('/auth/google',{method:'POST',body:{idToken}});await authenticated(data.user);closeModal();toast('Entraste con Google. ¡Bienvenid@!');if(!state.user.genderIdentity)editProfile(true);
  }).catch(error=>{
    const descriptions={'auth/popup-blocked':'Tu navegador bloqueó la ventana de Google. Permite ventanas emergentes para esta web y vuelve a intentar.','auth/popup-closed-by-user':'Cerraste la ventana de Google. Puedes volver a abrirla cuando quieras.','auth/unauthorized-domain':'Este dominio necesita autorizarse en Firebase → Authentication → Settings → Authorized domains. Para esta prueba abre http://localhost:3000.','auth/operation-not-allowed':'Activa el proveedor Google en Firebase → Authentication → Sign-in method.','auth/network-request-failed':'No se pudo conectar con Google. Revisa tu conexión.'};
    const message=descriptions[error.code]||error.message||'No se pudo iniciar sesión con Google.';if($('#authError'))$('#authError').textContent=message;else toast(message,true);
  }).finally(()=>{if(button?.isConnected)button.disabled=false;});
}
async function authenticated(user){state.user=user;await Promise.all([refreshProfiles(),refreshConversations(),refreshNews()]);startStream();route();}
async function logout(){await api('/auth/logout',{method:'POST',body:{}});cancelRecording();stopStream();state.user=null;window.dispatchEvent(new CustomEvent('xp:session',{detail:{id:null}}));state.conversations=[];state.messages=[];state.active=null;state.reply=null;clearAttachment();closeModal();route();toast('Sesión cerrada. Hasta la próxima aventura.');}
function positionAccountMenu(){
 const menu=$('.account-menu'),anchor=$('[data-action="account-menu"]');if(!menu||!anchor)return;
 const viewport=window.visualViewport,left=viewport?.offsetLeft||0,top=viewport?.offsetTop||0,width=viewport?.width||innerWidth,height=viewport?.height||innerHeight,rect=anchor.getBoundingClientRect();
 menu.style.width=Math.min(280,width-24)+'px';menu.style.right='auto';
 menu.style.left=Math.max(left+12,Math.min(rect.right-menu.offsetWidth,left+width-menu.offsetWidth-12))+'px';
 const y=Math.max(top+12,Math.min(rect.bottom+10,top+height-150));menu.style.top=y+'px';menu.style.maxHeight=Math.max(120,top+height-y-12)+'px';
 anchor.setAttribute('aria-expanded','true');
}
window.addEventListener('resize',positionAccountMenu);window.visualViewport?.addEventListener('resize',positionAccountMenu);window.visualViewport?.addEventListener('scroll',positionAccountMenu);
function accountMenu(){
  if($('.account-menu')){$('.account-menu').remove();return;}const menu=document.createElement('div');menu.className='account-menu';menu.innerHTML=`<div class="menu-user"><strong>${esc(state.user.name)}</strong><small>${esc(state.user.email)}</small></div><button data-action="my-profile">${icon('users')} Mi perfil</button><button data-action="avatar">${icon('image')} Cambiar ícono</button><button data-action="edit-profile">${icon('edit')} Editar perfil</button><button data-action="go-messages">${icon('chat')} Mis conversaciones</button><button type="button" data-push-settings>♧ Notificaciones</button><button type="button" data-install-app>↓ Instalar app</button><button data-action="password">${icon('lock')} Cambiar contraseña</button>${state.user.staff?'<button data-moderation="panel">✦ Moderación</button>':''}<button data-action="logout" style="color:var(--danger)">${icon('logout')} Cerrar sesión</button>`;document.body.append(menu);positionAccountMenu();
}
function openAvatarPicker(){
  if(!requireAuth())return;state.selectedAvatar=state.user.avatar;
  modal(`<div class="modal-kicker">TU IDENTIDAD, TU ELECCIÓN</div><h2 id="modalTitle">Elige a tu personaje.</h2><p class="modal-intro">Todos los rostros del universo, en un solo lugar.</p><label class="search-field">${icon('search')}<input id="avatarSearch" placeholder="Buscar un personaje…" aria-label="Buscar un personaje"></label><div class="avatar-count" id="avatarCount"></div><div class="avatar-grid" id="avatarGrid"></div><p class="form-error" id="avatarError"></p><button class="btn primary full" data-action="save-avatar" id="saveAvatar">Guardar mi ícono ${icon('check')}</button>`,true,'avatar');renderAvatarOptions('');
}
function renderAvatarOptions(q){const list=state.catalog.characters.filter(c=>norm(c.name).includes(norm(q))).sort((a,b)=>a.name.localeCompare(b.name,'es'));$('#avatarCount').textContent=`${list.length} de ${state.catalog.characters.length} personajes · Seleccionado: ${state.selectedAvatar}`;$('#avatarGrid').innerHTML=list.map(c=>`<button class="avatar-choice ${state.selectedAvatar===c.name?'selected':''}" data-action="choose-avatar" data-id="${esc(c.name)}" aria-label="Elegir ${esc(c.name)}" aria-pressed="${state.selectedAvatar===c.name}"><img src="${esc(c.image)}" alt="" loading="lazy"><span>${esc(c.name)}</span></button>`).join('')||'<p class="no-results">No encontramos ese personaje.</p>';}
async function updateMe(values){const result=await api('/me',{method:'PATCH',body:values});state.user=result.user;await refreshProfiles();renderChrome();return result.user;}
function editProfile(){
  if(!requireAuth())return;modal(`<div class="modal-kicker">ESTA HISTORIA ES TUYA</div><h2 id="modalTitle">Edita tu perfil.</h2><p class="modal-intro">Una pequeña presentación puede ser el inicio de una gran alianza.</p><form id="profileForm">${field('Nombre de usuario','profileName','text','Tu nombre',state.user.name)}${field('Biografía','profileBio','textarea','Cuéntanos algo de ti.',state.user.bio)}<p class="form-hint">Hasta 600 caracteres. Tu correo solo lo puedes ver tú.</p><p class="form-error" id="profileError"></p><button type="submit" class="btn primary full">Guardar cambios ${icon('check')}</button></form>`,false,'edit-profile');
  $('#profileForm').addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;try{await updateMe({name:$('#profileName').value,bio:$('#profileBio').value});closeModal();route();toast('Tu perfil está actualizado.');}catch(error){$('#profileError').textContent=error.message;}finally{btn.disabled=false;}});
}
function passwordModal(){
  if(!requireAuth())return;if(!state.user.hasPassword){modal(`<h2 id="modalTitle">Tu cuenta usa Google o Firebase.</h2><p class="modal-intro">La contraseña se gestiona con el proveedor de tu cuenta.</p><a class="btn secondary full" href="https://myaccount.google.com/security" target="_blank" rel="noopener">Abrir seguridad de Google ${icon('external')}</a>`);return;}
  modal(`<h2 id="modalTitle">Actualiza tu contraseña.</h2><p class="modal-intro">Necesitas tu contraseña actual. Al guardar se cerrarán las demás sesiones.</p><form id="passwordForm">${field('Contraseña actual','currentPassword','password')}${field('Nueva contraseña','newPassword','password','Mínimo 8 caracteres')}${field('Repetir nueva contraseña','confirmPassword','password')}<p class="form-error" id="passwordError"></p><button type="submit" class="btn primary full">Guardar contraseña</button></form>`);
  $('#passwordForm').addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;try{if($('#newPassword').value!==$('#confirmPassword').value)throw new Error('Las contraseñas no coinciden.');await api('/me/password',{method:'POST',body:{current:$('#currentPassword').value,password:$('#newPassword').value}});startStream();closeModal();toast('Contraseña actualizada.');}catch(error){$('#passwordError').textContent=error.message;}finally{btn.disabled=false;}});
}
async function follow(id){if(!requireAuth())return;const result=await api('/follow/'+encodeURIComponent(id),{method:'POST',body:{follow:!state.user.follows.includes(id)}});state.user=result.user;await refreshProfiles();if(state.route==='comunidad')communityResults();else if(state.route==='perfil')renderProfile(id);else if(state.route==='universo')renderAbout();}
async function saveContent(id){if(!requireAuth())return;const was=saved(id);await updateMe({saved:was?state.user.saved.filter(v=>v!==id):[...state.user.saved,id]});$$(`[data-action="save"][data-id="${CSS.escape(id)}"]`).forEach(btn=>{btn.classList.toggle('saved',!was);btn.setAttribute('aria-pressed',String(!was));btn.innerHTML=icon(was?'plus':'check');btn.setAttribute('aria-label',(was?'Añadir a':'Quitar de')+' mi lista');});if(state.route==='guardados')renderSaved();toast(was?'Quitado de tu lista.':'Guardado en tu lista.');}
function contentModal(id,kind){const item=allContent().find(c=>c.id===id&&(!kind||c.kind===kind));if(!item)return;modal(`<div class="modal-kicker">${esc(item.kind)} · ${esc(item.meta)}</div><h2 id="modalTitle">${esc(item.name)}</h2><img src="${esc(contentArt(item))}" alt="${esc(item.name)}" style="width:100%;max-height:260px;border-radius:13px;margin:14px 0 21px"><p class="modal-intro">${esc(item.desc)}</p>${item.disabled||!item.url?'<div class="notice">Esta temporada aún no tiene un enlace disponible. Vuelve pronto para descubrir su próximo capítulo.</div>':`<a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer" class="btn primary full">${esc(item.actionLabel||'Explorar')} ${icon('external')}</a>`}`);}
async function newsLike(id){if(!requireAuth())return;await api('/news/'+id+'/like',{method:'POST',body:{liked:!state.news.find(n=>n.id===id)?.liked}});await refreshNews();if(state.route==='noticias')renderNews();if(state.route==='inicio')renderHome();}
async function connectionsModal(id,following){if(!requireAuth())return;const p=getProfile(id);if(!p)return;const result=await api('/profiles/'+encodeURIComponent(id)+'/'+(following?'following':'followers'));modal(`<h2 id="modalTitle">${following?'Siguiendo':'Seguidores'} de ${esc(p.name)}</h2><div class="selection-list">${result.profiles.map(p=>personRow(p,'profile')).join('')||'<p class="no-results">Todavía no hay perfiles aquí.</p>'}</div>`);}
const personRow=(p,action='start-dm',checkbox=false)=>`<${checkbox?'label':'button'} class="person-row" ${checkbox?'':`data-action="${action}" data-id="${esc(p.id)}"`}>${avatar(p)}<span class="person-meta"><strong>${esc(p.name)}</strong><small>${p.character?'Personaje del universo':p.online?'En línea':'Cuenta registrada'}</small></span>${checkbox?`<input type="checkbox" name="groupMember" value="${esc(p.id)}">`:icon('arrow')}</${checkbox?'label':'button'}>`;

/* Mensajes */
function chatTitle(c){return c.type==='group'?c.title:c.members.find(m=>m.id!==state.user?.id)?.name||'Conversación';}
function chatAvatar(c){return c.type==='group'?`<span class="group-avatar">${esc(c.title.slice(0,2).toUpperCase())}</span>`:chatProfileLink(c.members.find(m=>m.id!==state.user?.id)||{id:'char:dani',name:'Dani'});}
function messagePreview(m){return !m?'Comienza una conversación':m.type==='image'?'▧ Imagen':m.type==='video'?'▶ Video':m.type==='audio'?'♫ Nota de voz':m.type==='sticker'?'✦ Sticker':m.type==='deleted'?'Mensaje eliminado':m.text;}
function renderMessenger(){
  $('#main').innerHTML=`<div class="messages-heading"><div><h1>Tus conversaciones.</h1><p>Una buena historia comienza con un «hola».</p></div><span class="pill lime">${icon('lock')} SOLO MIEMBROS DEL CHAT</span></div>`;
  if(!state.user){$('#main').insertAdjacentHTML('beforeend',`<div class="panel">${empty('Tu gente, a un mensaje de distancia.','Crea tu cuenta o inicia sesión para conversar con otros miembros, crear grupos y compartir momentos.','login','Entrar a mis mensajes','chat')}</div>`);return;}
  $('#main').insertAdjacentHTML('beforeend',`<section class="messenger" id="messenger" aria-label="Mensajería"><aside class="conversation-panel"><div class="conversation-tools"><div class="title-row"><h2>Mensajes <span class="pill" id="chatCount">${state.conversations.length}</span></h2><div class="button-row"><button class="icon-button" data-action="new-group" title="Crear grupo" aria-label="Crear grupo">${icon('users')}</button><button class="icon-button" data-action="new-chat" title="Nueva conversación" aria-label="Nueva conversación">${icon('edit')}</button></div></div><label class="search-field">${icon('search')}<input id="chatSearch" placeholder="Buscar una conversación…" aria-label="Buscar conversaciones" value="${esc(state.chatQuery)}"></label><div class="chat-filters"><button data-action="chat-filter" data-id="todos" class="chip ${state.chatFilter==='todos'?'active':''}">Todos</button><button data-action="chat-filter" data-id="sin-leer" class="chip ${state.chatFilter==='sin-leer'?'active':''}">Sin leer</button><button data-action="chat-filter" data-id="grupos" class="chip ${state.chatFilter==='grupos'?'active':''}">Grupos</button></div></div><div class="conversation-list" id="conversationList"></div></aside><section class="chat-pane" id="chatPane" aria-label="Conversación activa"><div class="chat-placeholder">${empty('Aquí comienzan las buenas historias.','Selecciona una conversación o escribe a alguien de la comunidad.','new-chat','Nuevo mensaje','chat')}</div></section></section>`);
  renderConversationList();if(state.active&&state.conversations.some(c=>c.id===state.active))openChat(state.active);else state.active=null;
}
function renderConversationList(){
  if(!$('#conversationList')||!state.user)return;let list=state.conversations.filter(c=>norm(chatTitle(c)).includes(norm(state.chatQuery))&&(state.chatFilter!=='sin-leer'||c.unread>0)&&(state.chatFilter!=='grupos'||c.type==='group'));
  $('#conversationList').innerHTML=list.map(c=>`<article class="conversation-item ${state.active===c.id?'active':''}">${c.type==='group'?`<button class="conversation-group" data-action="open-chat" data-id="${esc(c.id)}" aria-label="Abrir ${esc(chatTitle(c))}">${chatAvatar(c)}</button>`:chatAvatar(c)}<button class="conversation-open" data-action="open-chat" data-id="${esc(c.id)}" aria-label="${esc(chatTitle(c))}${c.unread?', '+c.unread+' sin leer':''}"><span class="conversation-copy"><span class="conversation-topline"><strong>${esc(chatTitle(c))}</strong><time>${shortDate(c.last?.created||c.created)}</time>${c.unread?`<span class="unread-badge">${c.unread}</span>`:''}</span><p>${c.last?.sender.id===state.user.id?'Tú: ':''}${esc(messagePreview(c.last))}</p></span></button></article>`).join('')||`<p class="no-results">${state.conversations.length?'No hay conversaciones con este filtro.':'Todavía no tienes chats. Empieza uno con el botón de arriba.'}</p>`;
  if($('#chatCount'))$('#chatCount').textContent=state.conversations.length;
}
async function openChat(id){
  if(state.active!==id)cancelRecording();const c=state.conversations.find(c=>c.id===id);if(!c||!state.user)return;
  state.active=id;state.reply=null;state.messageSearch='';state.messages=[];clearAttachment();state.requestSequence++;const sequence=state.requestSequence;
  $('#messenger')?.classList.add('chat-open');renderConversationList();
  let draft='';try{draft=sessionStorage.getItem('xp-draft:'+state.user.id+':'+id)||'';}catch{}
  $('#chatPane').innerHTML=`<header class="chat-header"><button class="icon-button mobile-back" data-action="chat-back" aria-label="Volver a conversaciones">${icon('back')}</button><span id="activeChatAvatar">${chatAvatar(c)}</span><div style="min-width:0"><h3 id="activeChatTitle">${esc(chatTitle(c))}</h3><div class="chat-status" id="chatStatus"></div></div><div class="header-actions"><button class="icon-button" data-action="message-search" aria-label="Buscar en esta conversación">${icon('search')}</button><button class="icon-button" data-action="chat-info" aria-label="Información de la conversación">${icon('info')}</button></div></header><div id="chatSearchArea"></div><div class="chat-history" id="chatHistory" role="log" aria-label="Mensajes de la conversación" aria-live="polite"><div class="loading-screen" style="min-height:150px"><span class="spinner"></span></div></div><div class="typing-indicator" id="typingIndicator" aria-live="polite"></div><div class="composer-area"><div id="replyArea"></div><div id="attachmentArea"></div><div id="recordingArea"></div><div class="composer"><button class="icon-button" data-chat="composer-emoji" aria-label="Añadir un emoji">${icon('smile')}</button><button class="icon-button" data-chat="stickers" aria-label="Enviar un sticker">${icon('sticker')}</button><button class="icon-button" data-action="attach" aria-label="Adjuntar imagen o video">${icon('image')}</button><textarea id="messageInput" rows="1" maxlength="5000" placeholder="Escribe un mensaje…" aria-label="Escribe un mensaje">${esc(draft)}</textarea><button class="icon-button" data-action="record" id="recordButton" aria-label="Grabar nota de voz">${icon('mic')}</button><button class="send-button" data-action="send" id="sendButton" aria-label="Enviar mensaje">${icon('send')}</button></div><div class="composer-caption"><span>Enter para enviar · Shift + Enter para un salto</span><span>Mensajes privados entre miembros</span></div></div>`;
  updateChatStatus();
  try{
    const result=await api('/conversations/'+encodeURIComponent(id)+'/messages');if(sequence!==state.requestSequence||state.active!==id||!$('#chatHistory'))return;
    state.messages=result.messages;state.hasMore=result.hasMore;renderMessages(true);await markRead(id);
  }catch(error){if(sequence===state.requestSequence&&$('#chatHistory'))$('#chatHistory').innerHTML=`<p class="no-results">${esc(error.message)}</p><button class="load-more" data-action="retry-chat">Reintentar</button>`;}
}
function updateChatStatus(){const c=state.conversations.find(c=>c.id===state.active);if(!c||!$('#chatStatus'))return;const other=c.members.find(m=>m.id!==state.user?.id);$('#chatStatus').textContent=c.type==='group'?c.members.length+' miembros · Chat de grupo':other?.online?'En línea ahora':'Cuenta de la comunidad';$('#chatStatus').classList.toggle('online',c.type==='dm'&&!!other?.online);$('#activeChatTitle').textContent=chatTitle(c);$('#activeChatAvatar').innerHTML=chatAvatar(c);}
function linkify(text){return esc(text).replace(/https?:\/\/[^\s<]+/g,url=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${url}</a>`);}
async function markRead(id){if(document.visibilityState!=='visible'||state.route!=='mensajes'||state.active!==id)return;await api('/conversations/'+encodeURIComponent(id)+'/read',{method:'POST',body:{}});const c=state.conversations.find(c=>c.id===id);if(c)c.unread=0;renderConversationList();renderChrome();}
async function refreshConversations(){if(!state.user)return;const result=await api('/conversations');state.conversations=result.conversations;renderConversationList();renderChrome();updateChatStatus();}
async function refreshProfiles(){const result=await api('/profiles');state.profiles=result.profiles;}
async function refreshNews(){const result=await api('/news');state.news=result.likes;}
function newChat(group=false){
  if(!requireAuth())return;const members=state.profiles.filter(p=>!p.character&&p.id!==state.user.id);
  modal(`<div class="modal-kicker">${group?'LAS MEJORES HISTORIAS SON EN EQUIPO':'DA EL PRIMER PASO'}</div><h2 id="modalTitle">${group?'Crea tu grupo.':'Un mensaje, una nueva alianza.'}</h2><p class="modal-intro">${group?'Elige a tu gente y ponle un nombre a esta historia.':'Las conversaciones se abren con cuentas reales de la comunidad.'}</p>${group?field('Nombre del grupo','groupTitle','text','Ej. Exploradores sin fronteras'):''}<label class="search-field">${icon('search')}<input id="personSearch" placeholder="Buscar en la comunidad…" aria-label="Buscar una cuenta"></label><div class="selection-list" id="personList">${members.map(p=>personRow(p,'start-dm',group)).join('')||'<p class="no-results">Aún no hay otras cuentas registradas. Invita a alguien a crear la suya para comenzar.</p>'}</div>${group?'<p class="form-error" id="groupError"></p><button class="btn primary full" data-action="create-group" style="margin-top:16px">Crear grupo</button>':''}<div class="notice" style="margin-top:18px">Los personajes son íconos y perfiles de la competencia. Cada persona necesita registrar su propia cuenta para recibir mensajes.</div>`,false,group?'new-group':'new-chat');
}
async function startDM(id){if(!requireAuth())return;const result=await api('/conversations',{method:'POST',body:{members:[id],type:'dm'}});closeModal();await refreshConversations();state.active=result.conversation.id;if(state.route!=='mensajes')go('mensajes');else openChat(state.active);}
async function createGroup(){const ids=$$('input[name=groupMember]:checked').map(el=>el.value);const btn=$('[data-action="create-group"]');btn.disabled=true;try{const result=await api('/conversations',{method:'POST',body:{type:'group',title:$('#groupTitle').value,members:ids}});closeModal();await refreshConversations();state.active=result.conversation.id;if(state.route!=='mensajes')go('mensajes');else openChat(state.active);}catch(error){$('#groupError').textContent=error.message;}finally{btn.disabled=false;}}
function chatInfo(){const c=state.conversations.find(c=>c.id===state.active);if(!c)return;const admin=c.members.find(m=>m.id===state.user.id)?.role==='admin';modal(`<h2 id="modalTitle">${esc(chatTitle(c))}</h2><p class="modal-intro">${c.type==='group'?'Un espacio para compartir con tu gente.':'Conversación privada entre dos miembros.'}</p>${c.type==='group'&&admin?`<label class="form-field">Nombre del grupo<input id="groupRename" value="${esc(c.title)}" maxlength="70"></label><button class="btn secondary full" data-action="rename-group">Guardar nombre</button><button class="btn secondary full" style="margin-top:8px" data-action="add-members">Añadir miembros</button>`:''}<div class="section-head"><h3 style="margin:0">${c.members.length} miembros</h3></div><div class="selection-list">${c.members.map(m=>`<button class="person-row" data-action="profile" data-id="${esc(m.id)}">${avatar(m)}<span class="person-meta"><strong>${esc(m.name)}</strong><small>${m.role==='admin'?'Administrador · ':''}${m.online?'En línea':'Miembro del chat'}</small></span></button>`).join('')}</div>${c.type==='group'?'<button class="btn danger full" data-action="leave-group" style="margin-top:20px">Salir del grupo</button>':''}`);}
function setReply(id){state.reply=state.messages.find(m=>m.id===id);closeModal();if(!state.reply)return;$('#replyArea').innerHTML=`<div class="reply-banner"><div><strong>Respondiendo a ${esc(state.reply.sender.name)}</strong><p>${esc(messagePreview(state.reply))}</p></div><button class="icon-button" data-action="cancel-reply" aria-label="Cancelar respuesta">${icon('close')}</button></div>`;$('#messageInput')?.focus();}
function clearAttachment(){$$('audio,video',$('#attachmentArea')||document.createElement('div')).forEach(a=>a.pause());if(state.attachment?.preview)URL.revokeObjectURL(state.attachment.preview);state.attachment=null;if($('#attachmentArea'))$('#attachmentArea').innerHTML='';if($('#attachmentInput'))$('#attachmentInput').value='';}
async function fileToBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.readAsDataURL(file);});}
async function sendMessage(){
  if(state.sending||state.audioProcessing||!state.user||!state.active||!$('#messageInput'))return;if(state.recording){toast('Termina la nota de voz antes de enviar.',true);return;}
  const input=$('#messageInput'),text=input.value.trim(),attachment=state.attachment;if(!text&&!attachment){input.focus();return;}
  const active=state.active,reply=state.reply;
  const fingerprint=JSON.stringify([text,attachment?.id||'',reply?.id||'']);
  state.sendAttempts=state.sendAttempts||new Map();const previous=state.sendAttempts.get(active);
  const id=attachment?.id||(previous?.fingerprint===fingerprint?previous.id:crypto.randomUUID());
  state.sendAttempts.set(active,{id,fingerprint});state.sending=true;$('#sendButton').disabled=true;
  try{
    const values={id,text,replyTo:reply?.id,type:attachment?.type||'text'};if(attachment)Object.assign(values,{data:await fileToBase64(attachment.file),mime:attachment.file.type,filename:attachment.filename,durationMs:attachment.durationMs||0});
    const result=await api('/conversations/'+encodeURIComponent(active)+'/messages',{method:'POST',body:values});
    state.sendAttempts.delete(active);
    if(state.active===active){if(input.value.trim()===text)input.value='';input.style.height='auto';state.reply=null;$('#replyArea').innerHTML='';if(state.attachment===attachment)clearAttachment();try{sessionStorage.removeItem('xp-draft:'+state.user.id+':'+active);}catch{}upsertMessage(result.message);renderMessages(true);await markRead(active);}
    await refreshConversations();
  }catch(error){toast(error.message,true);}finally{state.sending=false;if($('#sendButton'))$('#sendButton').disabled=false;}
}
function upsertMessage(message){const index=state.messages.findIndex(m=>m.id===message.id);if(index<0)state.messages.push(message);else state.messages[index]=message;state.messages.sort((a,b)=>a.created-b.created);}
async function olderMessages(){const id=state.active,history=$('#chatHistory'),height=history.scrollHeight;const result=await api('/conversations/'+encodeURIComponent(id)+'/messages?before='+state.messages[0].created);if(state.active!==id)return;state.messages=[...result.messages,...state.messages];state.hasMore=result.hasMore;renderMessages();history.scrollTop=history.scrollHeight-height;}
function stopStream(){state.stream?.close();state.stream=null;}
function startStream(){
  stopStream();if(!state.user)return;window.dispatchEvent(new CustomEvent('xp:session',{detail:{id:state.user.id}}));const stream=new EventSource('/api/events');state.stream=stream;
  stream.addEventListener('ready',()=>{setConnection(true);refreshConversations().catch(()=>{});refreshProfiles().catch(()=>{});if(state.active&&state.route==='mensajes')refreshActiveMessages().catch(()=>{});});
  stream.onerror=()=>setConnection(false);stream.onopen=()=>setConnection(true);
  stream.addEventListener('profiles',async()=>{try{const own=await api('/me');state.user=own.user;await refreshProfiles();renderChrome();if(state.route==='comunidad')communityResults();if(state.route==='perfil'&&!$('#postForm'))renderProfile(decodeURIComponent(location.hash.split('/')[1]||''));}catch{}});
  stream.addEventListener('news',async()=>{await refreshNews();if(state.route==='noticias')renderNews();});
  stream.addEventListener('presence',event=>{const p=JSON.parse(event.data);const profile=getProfile(p.id);if(profile)profile.online=p.online;for(const c of state.conversations)for(const m of c.members)if(m.id===p.id)m.online=p.online;renderConversationList();updateChatStatus();});
  stream.addEventListener('conversations',async()=>{await refreshConversations();if(state.active&&!state.conversations.some(c=>c.id===state.active)){state.active=null;if(state.route==='mensajes')renderMessenger();}});
  stream.addEventListener('message',async event=>{
    const payload=JSON.parse(event.data),visible=state.route==='mensajes'&&state.active===payload.conversation&&$('#chatHistory');
    if(visible){upsertMessage(payload.message);renderMessages();if(payload.message.sender.id!==state.user?.id)markRead(payload.conversation).catch(()=>{});}
    await refreshConversations();
  });
  stream.addEventListener('read',async event=>{const payload=JSON.parse(event.data);await refreshConversations();if(payload.conversation===state.active&&state.route==='mensajes')renderMessages();});
  stream.addEventListener('typing',event=>{const p=JSON.parse(event.data);if(p.conversation!==state.active||!$('#typingIndicator'))return;$('#typingIndicator').textContent=p.name+' está escribiendo…';clearTimeout(state.typingTimer);state.typingTimer=setTimeout(()=>{if($('#typingIndicator'))$('#typingIndicator').textContent='';},3000);});
}
async function refreshActiveMessages(){const id=state.active;const r=await api('/conversations/'+encodeURIComponent(id)+'/messages');if(state.active===id&&$('#chatHistory')){state.messages=r.messages;state.hasMore=r.hasMore;renderMessages();await markRead(id);}}

/* Una sola capa de eventos para conservar selección, borradores y accesibilidad. */
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button){if(!event.target.closest('.account-menu'))$('.account-menu')?.remove();return;}const action=button.dataset.action,id=button.dataset.id;
  try{
    switch(action){
      case'login':openAuth('login');break;case'register':openAuth('register');break;case'google':googleLogin();break;case'close-modal':closeModal();break;case'account-menu':accountMenu();break;case'logout':await logout();break;case'my-profile':go('perfil/'+encodeURIComponent(state.user.id));break;case'profile':closeModal();go('perfil/'+encodeURIComponent(id));break;case'go-messages':go('mensajes');break;case'search':go('buscar');break;case'go-explore':go('explorar');break;case'go-community':go('comunidad');break;case'retry':location.reload();break;
      case'toggle-password':{const input=$('#'+id);input.type=input.type==='password'?'text':'password';button.setAttribute('aria-label',input.type==='password'?'Mostrar contraseña':'Ocultar contraseña');break;}
      case'content':contentModal(id,button.dataset.kind);break;case'save':await saveContent(id);break;case'explore-filter':go('explorar/'+id);break;case'community-tab':state.communityTab=id;state.query='';renderCommunity();break;case'follow':button.disabled=true;try{await follow(id);}finally{button.disabled=false;}break;case'news-like':button.disabled=true;try{await newsLike(id);}finally{button.disabled=false;}break;
      case'avatar':openAvatarPicker();break;case'choose-avatar':state.selectedAvatar=id;renderAvatarOptions($('#avatarSearch').value);break;
      case'save-avatar':button.disabled=true;try{await updateMe({avatar:state.selectedAvatar});closeModal();route();toast('Tu nuevo ícono ya está guardado.');}catch(error){$('#avatarError').textContent=error.message;}finally{button.disabled=false;}break;
      case'edit-profile':editProfile();break;case'password':passwordModal();break;case'followers':await connectionsModal(id,false);break;case'following':await connectionsModal(id,true);break;
      case'new-chat':newChat();break;case'new-group':newChat(true);break;case'start-dm':await startDM(id);break;case'create-group':await createGroup();break;case'open-chat':await openChat(id);break;case'retry-chat':await openChat(state.active);break;
      case'chat-back':cancelRecording();state.active=null;state.requestSequence++;$('#messenger')?.classList.remove('chat-open');renderConversationList();break;
      case'chat-filter':state.chatFilter=id;$$('.chat-filters .chip').forEach(b=>b.classList.toggle('active',b.dataset.id===id));renderConversationList();break;
      case'chat-info':chatInfo();break;
      case'add-members':{const c=state.conversations.find(c=>c.id===state.active),candidates=state.profiles.filter(p=>!p.character&&!c.members.some(m=>m.id===p.id));modal(`<h2 id="modalTitle">Suma a más exploradores.</h2><div class="selection-list">${candidates.map(p=>personRow(p,'',true)).join('')||'<p class="no-results">No hay más cuentas para añadir.</p>'}</div><button class="btn primary full" data-action="confirm-add-members" style="margin-top:18px">Añadir al grupo</button>`);break;}
      case'confirm-add-members':await api('/conversations/'+encodeURIComponent(state.active)+'/members',{method:'POST',body:{members:$$('input[name=groupMember]:checked').map(el=>el.value)}});await refreshConversations();chatInfo();break;
      case'rename-group':await api('/conversations/'+encodeURIComponent(state.active),{method:'PATCH',body:{title:$('#groupRename').value}});closeModal();await refreshConversations();toast('Nombre del grupo actualizado.');break;
      case'leave-group':modal(`<h2 id="modalTitle">¿Salir de este grupo?</h2><p class="modal-intro">Dejarás de recibir sus mensajes. Otro miembro podrá volver a invitarte.</p><button class="btn danger full" data-action="confirm-leave">Sí, salir del grupo</button><button class="btn secondary full" data-action="close-modal" style="margin-top:8px">Quedarme</button>`);break;
      case'confirm-leave':await api('/conversations/'+encodeURIComponent(state.active),{method:'DELETE',body:{}});state.active=null;closeModal();await refreshConversations();renderMessenger();break;
      case'message-search':if($('#messageSearch')){$('#chatSearchArea').innerHTML='';state.messageSearch='';renderMessages();}else{$('#chatSearchArea').innerHTML=`<div class="chat-searchbar"><label class="search-field">${icon('search')}<input id="messageSearch" placeholder="Buscar en los mensajes cargados…" aria-label="Buscar en los mensajes cargados"></label><button class="icon-button" data-action="message-search" aria-label="Cerrar búsqueda">${icon('close')}</button></div>`;$('#messageSearch').focus();}break;
      case'message-options':messageOptions(id);break;case'reply':setReply(id);break;case'cancel-reply':state.reply=null;$('#replyArea').innerHTML='';break;
      case'react':await reactToMessage(id,button.dataset.emoji,button);break;
      case'delete-message':modal(`<h2 id="modalTitle">¿Eliminar este mensaje?</h2><p class="modal-intro">Se eliminará para todos los miembros del chat.</p><button class="btn danger full" data-action="confirm-delete-message" data-id="${id}">Eliminar para todos</button><button class="btn secondary full" data-action="close-modal" style="margin-top:8px">Cancelar</button>`);break;
      case'confirm-delete-message':await api('/messages/'+id,{method:'DELETE',body:{}});closeModal();break;
      case'edit-message':{const m=state.messages.find(m=>m.id===id);modal(`<h2 id="modalTitle">Edita tu mensaje.</h2>${field('Mensaje','editMessageText','textarea','',m.text)}<button class="btn primary full" data-action="save-message-edit" data-id="${id}">Guardar cambios</button>`);break;}
      case'save-message-edit':await api('/messages/'+id,{method:'PATCH',body:{text:$('#editMessageText').value}});closeModal();break;
      case'jump-message':{const el=$('#message-'+CSS.escape(id));if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('message-highlight');setTimeout(()=>el.classList.remove('message-highlight'),1600);}else toast('Carga los mensajes anteriores para ver el original.');break;}
      case'view-image':await openChatMediaViewer(id);break;
      case'attach':$('#attachmentInput').click();break;case'cancel-attachment':clearAttachment();break;case'record':await startRecording();break;case'stop-recording':stopRecording();break;case'cancel-recording':cancelRecording();if($('#recordingArea'))$('#recordingArea').innerHTML='';if($('#recordButton'))$('#recordButton').innerHTML=icon('mic');break;case'send':await sendMessage();break;case'older-messages':button.disabled=true;try{await olderMessages();}finally{button.disabled=false;}break;
    }
    if(action!=='account-menu'&&!['login','register'].includes(action))$('.account-menu')?.remove();
  }catch(error){toast(error.message,true);}
});
document.addEventListener('input',event=>{
  const input=event.target;
  if(input.id==='communitySearch'){state.query=input.value;communityResults();}
  if(input.id==='avatarSearch')renderAvatarOptions(input.value);
  if(input.id==='exploreSearch'){state.query=input.value;const items=exploreContent().filter(c=>norm(c.name+' '+c.meta).includes(norm(state.query)));$('#exploreResults').innerHTML=items.map(contentCard).join('')||'<p class="no-results">No encontramos esa temporada.</p>';}
  if(input.id==='globalSearch')searchResults(input.value);
  if(input.id==='personSearch')$$('.person-row',$('#personList')).forEach(el=>{el.hidden=!norm(el.textContent).includes(norm(input.value));});
  if(input.id==='chatSearch'){state.chatQuery=input.value;renderConversationList();}
  if(input.id==='messageSearch'){state.messageSearch=input.value;renderMessages();}
  if(input.id==='messageInput'){
    input.style.height='auto';input.style.height=Math.min(input.scrollHeight,120)+'px';
    try{sessionStorage.setItem('xp-draft:'+state.user.id+':'+state.active,input.value);}catch{}
    if(Date.now()-state.typingAt>1800&&input.value.trim()){state.typingAt=Date.now();api('/conversations/'+encodeURIComponent(state.active)+'/typing',{method:'POST',body:{}}).catch(()=>{});}
  }
});
document.addEventListener('keydown',event=>{
  if(event.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#modal').open){event.preventDefault();go('buscar');}
  if(event.target.id==='messageInput'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendMessage();}
});
function stageChatAttachment(file){
 if(!file)return false;const video=['video/mp4','video/webm'].includes(file.type),image=['image/jpeg','image/png','image/webp','image/gif'].includes(file.type);
 if((!image&&!video)||file.size>(video?6:4)*1024*1024){toast('Elige una imagen de hasta 4 MB o un video MP4/WebM de hasta 6 MB.',true);return false;}
 clearAttachment();state.attachment={file,filename:file.name||'imagen-pegada.png',type:video?'video':'image',preview:URL.createObjectURL(file),id:crypto.randomUUID()};attachmentPreview();return true;
}
$('#attachmentInput').addEventListener('change',event=>{if(!stageChatAttachment(event.target.files[0]))event.target.value='';});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal'))closeModal();});
$('#modal').addEventListener('close',()=>{state.modal=null;});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.user&&state.active)markRead(state.active).catch(()=>{});});
window.addEventListener('hashchange',route);window.addEventListener('offline',()=>setConnection(false));window.addEventListener('online',()=>{setConnection(true);if(state.user)startStream();});window.addEventListener('beforeunload',()=>cancelRecording());
function openPublicCatalog(){
  state.publicOnly=true;state.user=null;state.config={};state.news=[];state.communityTab='personajes';
  state.profiles=state.catalog.characters.map(c=>({id:'char:'+c.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,''),name:c.name,avatar:c.name,bio:'Personaje del universo The Xpedition.',stats:state.catalog.stats[c.name]||{},character:true,followers:'—',following:'—',online:false}));
  setConnection(false);route();
}
async function init(){
  try{
    if(location.protocol==='file:')throw new Error('Esta versión necesita el servidor para crear cuentas y compartir mensajes. Cierra este archivo y abre ABRIR XPEDITION.cmd.');
    if(location.hostname==='thexpedition.github.io'){const destination=new URL('https://the-xpedition-universe.onrender.com/');destination.hash=location.hash||'#inicio';destination.search=location.search;location.replace(destination.href);return;}
    state.publicOnly=false;
    const [catalog,details]=await Promise.all([fetch('catalog.json').then(r=>{if(!r.ok)throw new Error('No se pudo cargar el catálogo.');return r.json();}),fetch('content-details.json').then(r=>{if(!r.ok)throw new Error('No se pudo cargar la información de las temporadas.');return r.json();})]);catalog.details=details;state.catalog=catalog;
    if(location.hostname.endsWith('.github.io')){openPublicCatalog();return;}
    try{state.config=await api('/config');}catch(error){if(error.status===404){openPublicCatalog();return;}throw error;}
    const me=await api('/me');state.user=me.user;
    await Promise.all([refreshProfiles(),refreshNews(),state.user?refreshConversations():Promise.resolve()]);setConnection(true);route();loadFirebase();if(state.user)startStream();
  }catch(error){errorView(error);}
}
$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
